SELECT ur.user_id, r.role_code, r.role_name, CAST(ur.organization_id AS CHAR(20)) AS organization_id, o.organization_name FROM sys_user_role ur JOIN sys_role r ON r.id=ur.role_id LEFT JOIN sys_organization o ON o.id=ur.organization_id WHERE r.status='ENABLED' AND (ur.organization_id IS NULL OR o.id IS NOT NULL) AND ur.user_id IN #{id}
AND (ur.organization_id IS NULL OR ur.organization_id IN #{id}) AND 1=0
ORDER BY ur.user_id, o.organization_path, o.id, r.role_code

SELECT EXISTS(SELECT 1 FROM sys_user_role ur JOIN sys_role r ON r.id=ur.role_id
JOIN sys_user u ON u.id=ur.user_id WHERE ur.user_id=#{userId}
AND r.role_code='SYS_ADMIN' AND r.status='ENABLED' AND u.status='ENABLED')

SELECT EXISTS(
    SELECT 1
    FROM sys_user_organization
    WHERE user_id = #{userId}
      AND organization_id = #{organizationId}
)
